  ('NOV23-056', '6d18cfa0-6c82-4687-856b-4d186f6ed99c', 3, 60, 'weekly', null),
  ('NOV23-061', '6d18cfa0-6c82-4687-856b-4d186f6ed99c', 3, 70, 'weekly', null)
       ) as v(ref, route_id, weekday, seq, frequency, nth_of_month)
  join public.customers c
    on c.business_id = 'b7d18d8b-aa7c-4dd8-a37a-4ced75748239' and c.external_ref = v.ref
 where not exists (
   select 1 from public.route_stops x
    where x.route_id = v.route_id::uuid and x.weekday = v.weekday
      and x.customer_id = c.id and x.visit_no = 1 and x.active_to is null);
